def build_a1():
    print(f"Total raw A1 words defined: {len(A1_RAW)}")
    assert len(A1_RAW) == 300, f"Expected 300 A1 words, got {len(A1_RAW)}"
    
    words_data = []
    seen = set()
    for idx, item in enumerate(A1_RAW, start=1):
        word, pos, phonetic, meaning_th, meaning_en, example, synonyms, antonyms = item
        w_lower = word.lower().strip()
        if w_lower in seen:
            raise ValueError(f"Duplicate word in A1: {w_lower}")
        seen.add(w_lower)
        
        words_data.append({
            "id": f"v_a1_{idx:03d}",
            "word": w_lower,
            "part_of_speech": pos,
            "cefr_level": "A1",
            "phonetic": phonetic,
            "meaning_th": meaning_th,
            "meaning_en": meaning_en,
            "example_sentence": example,
            "synonyms": json.dumps(synonyms, ensure_ascii=False),
            "antonyms": json.dumps(antonyms, ensure_ascii=False),
            "frequency_tier": 1
        })
    
    with open("c:/MaMan/database/cefr_dataset/a1_words.json", "w", encoding="utf-8") as f:
        json.dump(words_data, f, ensure_ascii=False, indent=2)
    print(f"Successfully generated 300 A1 words to a1_words.json!")
    return words_data

if __name__ == "__main__":
    build_a1()
